import backoff
from six.moves.urllib.parse import urlencode, quote

GCP_CLIENT = None

@backoff.on_exception(backoff.expo, Exception, max_tries=2)
def save_file_obj(dest_path, file_obj, container, syndicate_name, content_type):
    bucket, real_container_name = _gcp_bucket(container)
    blob = bucket.blob(dest_path)
    blob.upload_from_file(
        file_obj,
        size=getattr(file_obj, 'size', None),
        content_type=content_type,
        rewind=True,
    )

    blob_url = blob.generate_signed_url(timedelta(hours=24*3000), method="GET")
    return blob_url, blob_url

@backoff.on_exception(backoff.expo, Exception, max_tries=2)
def retrieve_to_file_obj(src_path, file_obj, container):
    bucket, _ = _gcp_bucket(container)
    blob = bucket.get_blob(src_path)
    if blob:
        blob.download_to_file(file_obj)

@backoff.on_exception(backoff.expo, Exception, max_tries=2)
def delete_file(file_path, container):
    bucket, _ = _gcp_bucket(container)
    blob = bucket.get_blob(file_path)
    if blob:
        blob.delete()

@backoff.on_exception(backoff.expo, Exception, max_tries=2)
def delete_dir(dir_path, container):
    bucket, _ = _gcp_bucket(container)
    # The trailing slash keeps "12" from also matching "123/...".
    for blob in bucket.list_blobs(prefix=dir_path.rstrip('/') + '/'):
        blob.delete()


def _gcp_bucket(container_name):
    global GCP_CLIENT
    if not GCP_CLIENT:
        GCP_CLIENT = storage.Client()
    if settings.BUCKET_PREFIX:
        container_name = settings.BUCKET_PREFIX + container_name
    return GCP_CLIENT.bucket(container_name), container_name

